-- ============================================================================
-- Import Aset Tetap Lainnya (ATL, golongan 1.3.5) EKSTRAKOMPTABEL 2025 —
-- TAHAP 1: staging (2026-09-15).
--
-- Sumber: `Import ATL Ekstrakom - Copy.xlsx` (sheet 'ATL', kolom-per-kolom
-- IDENTIK dgn schema aset_awal_2026 -- pola sama dgn batch-batch sebelumnya).
-- PERINGATAN: Nama berkas menjanjikan ribuan baris (rentang terformat sampai
-- baris 173.265), TAPI isi SUNGGUHANNYA cuma 667 baris (baris 2..668) --
-- dibuktikan DUA CARA: pandas.read_excel (667) & penghitungan manual openpyxl
-- atas kolom A dari baris 2 s.d. 173.265 (667 sel terisi, sisanya kosong; sel
-- kosong PERTAMA persis di baris 669). Ini cuma styling/format-range Excel
-- yang meluber, bukan data -- jangan tertipu ukuran berkas (3,3 MB) atau nama
-- foldernya ("Saldo awal E ATL 2026").
--
-- Batch ini KECIL, jadi menyimpang dari pola CSV+Table-Editor batch-batch
-- besar sebelumnya: 667 baris DIBAWA LANGSUNG sbg literal VALUES di migrasi
-- ini (bukan lewat arsip-import/*.csv + import manual). Lebih auditable
-- utk skala ini (semua isi kelihatan di git diff, tak ada langkah klik-klik
-- Table Editor yg gagal senyap) & TIDAK melanggar pelajaran disk-exhaustion
-- 2026-09-14 (batch 41.820 baris) -- itu soal WAL dari INSERT besar; 667 baris
-- jauh di bawah ambang manapun yg pernah jadi masalah. CSV bersih tetap
-- ditulis ke arsip-import/stg_import_atl_ekstrakom.csv (gitignored) sbg
-- salinan cadangan, murni dokumentasi -- TIDAK dipakai proses import ini.
--
-- CATATAN ISI FILE (hasil analisis PENUH 667/667 baris, bukan sampel):
--   1. NIBAR: 100% unik (667), semua 45 digit, kepala SERAGAM 12023506
--      ([12][02=ekstra][3506=Kab.Kediri]). Catatan: nibar di kolom A
--      tersimpan sbg TEXT di file (dibuktikan lewat openpyxl data_only=True,
--      hasilnya str bukan angka) -- TAPI saat dibaca pandas.read_excel
--      kolomnya ter-infer jadi Python int. Dicek eksplisit: 0/667 mismatch
--      antara pembacaan mentah (string, dari openpyxl langsung) vs hasil
--      konversi pandas (Python int punya presisi arbitrer, beda dgn float64
--      yg cuma ~15-17 angka signifikan) -- jadi AMAN utk kasus ini, tapi jadi
--      pengingat: kolom 45-digit yg lolos jadi angka HARUS selalu dicocokkan
--      balik ke pembacaan string mentah sebelum dipakai, jangan dipercaya
--      buta. Nilai final di bawah diambil dari string openpyxl langsung.
--   2. golongan 100% "1.3.5"; kode barang ADA 18 VARIAN (bukan cuma 1-2 kode
--      "rusak berat" spt batch Aset Lain-Lain 20260914_03) -- ini batch buku
--      perpustakaan sekolah + sedikit alat musik/kesenian yg SUNGGUHAN
--      golongan 1.3.5, bukan reklasifikasi barang rusak. Semua 18 kode
--      terdaftar aktif di admin_kodefikasi_bmd (diverifikasi via LEFT JOIN
--      ke DB langsung, 2026-09-15, 0 yg tak terdaftar) & uraian_barang di
--      file COCOK PERSIS 1:1 per kode (0 kode dgn >1 varian uraian).
--   3. intra_ekstra 100% "Ekstra" di file -> di-lowercase-kan 'ekstra' saat
--      dibangun (CHECK saldo_awal_2026_intra_ekstra_check cuma menerima
--      huruf kecil). TIDAK dihitung ulang dari batas_kapitalisasi -- kebijakan
--      asli barang, bukan data yg perlu dihitung ulang (pola 20260716_04/
--      20260720_01).
--   4. ATL (1.3.5) TIDAK disusutkan (CLAUDE.md: disusutkan:false utk Tanah
--      1.3.1/ATL 1.3.5/KDP 1.3.6) -> nilai_buku_awal == nilai_perolehan di
--      SEMUA 667 baris (0 selisih, toleransi 0,01) -> akumulasi_2025 akan
--      dihitung 0 utk semua baris di TAHAP 2, persis pola ATL Diknas
--      (20260720_01/02). Kolom masa_manfaat_smt/sisa_masa_manfaat_smt/
--      beban_penyusutan_per_smt 100% KOSONG di file (0/667 terisi) -- TIDAK
--      ikut staging, payload ledger TAHAP 2 mengisinya NULL langsung.
--   5. skpd_id: 103 SKPD berbeda, SEMUA valid di admin_skpd (diverifikasi
--      LEFT JOIN ke DB, 2026-09-15, 0 yg tak terdaftar) -- didominasi sekolah/
--      UPT di bawah Dinas Pendidikan (penggunaan_pengamanan berisi nama
--      sekolah spt "SDN Gambyok II", "UPTD SMPN 2 Tarokan") + satu blok 105
--      baris milik langsung "Dinas Kearsipan dan Perpustakaan" (skpd_id 21,
--      seluruhnya tgl_perolehan 2025-07-08, asal_usul "Pengadaan APBD",
--      merek_tipe terisi -- beda pola dari sisanya yg "Pembelian" sekolah).
--   6. jumlah SELALU 1 (667/667); jumlah x harga_satuan == nilai_perolehan di
--      SEMUA baris (0 selisih) -- data konsisten, satu baris = satu unit/lot.
--   7. kondisi_barang 100% "Baik" (cocok CHECK aset_kondisi_barang_check
--      persis, termasuk kapitalisasi huruf).
--   8. tgl_perolehan 2017-06-30 s.d. 2025-07-08 -- TAK ADA yg di masa depan &
--      TAK ADA yg sesudah 2025-12-31 (baseline ledger), aman utk backfill
--      retroaktif 'saldo_awal' (sudah di-whitelist fn_cek_tahun_buku).
--   9. tahun_pengadaan DICEK terhadap .year dari tgl_perolehan: 0/667
--      mismatch (beda dgn insiden 20260914_03 poin 9, yg bermasalah krn bug
--      serial-date Excel) -- di file ini tahun_pengadaan memang berisi
--      TANGGAL PENUH yg sama dgn tgl_perolehan, bukan cuma angka tahun; jadi
--      TETAP diturunkan dari .year tgl_perolehan (konsisten dgn pola
--      batch2 lain), bukan dibaca mentah dari kolom itu.
--  10. Kolom populasi PARSIAL (dipertahankan APA ADANYA, bukan dipaksa
--      seragam): spesifikasi_lainnya 239/667, merek_tipe 105/667 (persis
--      berhimpit dgn blok "Dinas Kearsipan dan Perpustakaan" 105 baris di
--      poin 5), keterangan 667/667, penggunaan_pengamanan 667/667.
--      KOSONG TOTAL (0/667, TIDAK ikut staging): no_polisi/no_bpkb/
--      no_rangka/no_mesin, alamat_detail, luas, dokumen kepemilikan,
--      jenis_hak, wilayah_kode, latitude/longitude, foto_paths, pemanfaatan,
--      masa_manfaat_smt/akumulasi_2025/sisa_masa_manfaat_smt/
--      beban_penyusutan_per_smt, created_at.
--  11. nama_barang 44/667 baris ber-spasi tepi (mis. "Ilmu Pengetahuan
--      Umum ") -> di-trim saat dibangun. Tak ada literal noise '-'/'~'/'N/A'
--      di kolom teks mana pun (diperiksa eksak).
--  12. Presisi desimal: nilai_perolehan/nilai_buku_awal/harga_satuan
--      dibulatkan 2 desimal (max scale terlihat di file = 2, 0 baris > 2) --
--      tak ada derau floating-point yg perlu diratakan spt batch2 sebelumnya.
--  13. Tabrakan NIBAR terhadap aset/aset_awal_2026 = 0, DIBUKTIKAN lewat
--      query LEFT JOIN eksplisit ke seluruh 667 NIBAR (2026-09-15) -- bukan
--      diasumsikan dari "golongan 1.3.5 ekstra masih kosong" (per 2026-09-15
--      golongan 1.3.5 = 173.262 baris, 100% INTRA, 0 EKSTRA, jadi batch ini
--      golongan+intra_ekstra yg BENAR-BENAR belum pernah diisi -- tapi
--      pelajaran 20260819_02 tetap: NIBAR bisa berpindah pemilik, jadi
--      dicek eksak per-NIBAR, bukan cuma per-keranjang).
--  14. Spot-check dobel-hitung (barang identik nilai+tgl+skpd yg sudah
--      AKTIF di aset, golongan APA PUN -- pola ATL Diknas 20260720_02):
--      29 baris kena / 13 grup identitas / Rp6.208.600 dari total batch
--      Rp233.642.913,48 (2,66%) -- 21 baris di golongan 1.3.5 sendiri (SAMA
--      spt ATL Diknas: barang beda dgn harga+tanggal kebetulan sama, wajar
--      utk buku/alat yg dibeli borongan), 8 baris di 1.3.2 (Peralatan&Mesin,
--      skpd_id 88, total Rp5,1jt -- juga wajar, harga satuan bulat). NIBAR
--      100% unik memastikan ini bukan baris yg SAMA, cuma kebetulan identitas
--      angka. AMAN, sepadan dgn preseden 20260720_02 (0,29%) -- proporsinya
--      lebih tinggi krn batch jauh lebih kecil (667 vs 149.846), bukan krn
--      lebih berisiko.
--
-- TOTAL (sesudah dibulatkan 2 desimal): nilai_perolehan = nilai_buku_awal =
-- Rp233.642.913,48 ; akumulasi_2025 = Rp0,00 (ATL tak pernah disusutkan).
--
-- PRASYARAT: fn_cek_tahun_buku sudah mem-whitelist 'saldo_awal' retroaktif
-- (sudah dipakai batch-batch sebelumnya, terverifikasi ada di produksi).
-- Re-runnable / idempotent: TRUNCATE di bawah aman diulang; guard NOT EXISTS
-- ada di TAHAP 2 (20260915_02).
-- ============================================================================

CREATE TABLE IF NOT EXISTS stg_import_atl_ekstrakom (
  nibar                 text,
  kode                  text,
  nama_barang           text,
  skpd_id               bigint,
  intra_ekstra          text,
  nilai_perolehan       numeric,
  tgl_perolehan         date,
  nilai_buku_awal       numeric,
  spesifikasi_lainnya   text,
  merek_tipe            text,
  uraian_barang         text,
  keterangan            text,
  jumlah                int,
  satuan                text,
  harga_satuan          numeric,
  penggunaan_pengamanan text,
  asal_usul             text,
  kondisi_barang        text,
  tahun_pengadaan       int,
  golongan              text
);

